// Parse and structure the AI analysis
const aiResponse = $input.item.json.message.content;
let analysis;
try {
  analysis = JSON.parse(aiResponse);
} catch (e) {
  analysis = { error: 'Failed to parse AI response', raw: aiResponse };
}

const report = {
  report_type: 'weekly_trends',
  generated_at: new Date().toISOString(),
  period: {
    start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  },
  niche: $env.BUSINESS_NICHE || 'marketing digital',
  analysis: analysis,
  agent_id: 'marketing-strategist',
  workflow_id: 'WF-STRATEGY-TRENDS'
};

return { json: report };

